      "includeItemList": {
        "type": "boolean",
        "description": "剪枝：是否保留商品明细行；默认 false",
        "default": false
      }
    }
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "structured": {
        "type": "object",
        "description": "结构化数据"
      },
      "analysis": {
        "type": "string",
        "description": "状态解读与说明"
      }
    }
  }
}

