      },
      "enrichedContext": {
        "type": "object",
        "description": "上游合并的上下文，可含 country/destinationCountry/productLine 等",
        "additionalProperties": true
      }
    }
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "structured": {
        "type": "object",
        "description": "产品信息结构化结果",
