            "type": "string"
          },
          "productLine": {
            "type": "string"
          },
          "matchedProducts": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "name": {
                  "type": "string"
                },
                "category": {
                  "type": "string"
                },
                "weightLimit": {
                  "type": "string"
                },
                "dimensionLimit": {
                  "type": "string"
                },
                "deliveryTime": {
                  "type": "string"
                }
              }
            }
          },
          "confidence": {
            "type": "string",
            "enum": [
              "high",
              "medium",
              "low"
            ]
          }
        }
      },
      "analysis": {
        "type": "string",
        "description": "产品介绍、规格说明、限制解读（自然语言）"
      }
    }
  }
}

