manifest:
{
  "id": "outbound-order-status",
  "domain": "outbound",
  "name": "出库单状态解读",
  "description": "支持在同一入参中识别并处理三类出库相关标识：万邑通出库主单号（WO）、快递跟踪号、卖家/平台订单号（后两类格式可能相近，工作流内会按列表接口依次尝试解析）。可根据拉取结果归纳出库状态与关键字段（跟踪号、承运商、子单等）；不做操作建议，不承诺面单获取方式。编排提示：需要先拿到规范化出库上下文或跟踪号再查尾程/轨迹时，可优先调用本专家，再用其 structured 或原始 JSON 中的单号调用轨迹类专家。Use when 用户需要根据万邑通出库数据了解订单当前状态与字段含义，或编排器中需在查轨迹前解析客户给的任意单号。",
  "capabilities": [
    "出库单状态",
    "暂存",
    "增值",
    "多标识解析（出库单号 WO / 跟踪号 / 卖家订单号）",
    "编排前置：可先解析再查轨迹"
  ],
  "version": "0.1.0",
  "inputSchema": {
    "type": "object",
    "required": [],
    "properties": {
      "outboundOrderNos": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "出库相关标识列表（无需事先区分类型）：万邑通出库主单号（WO+数字）、快递跟踪号、或卖家/平台订单号。非 WO 时由工作流按 id/54 先 trackingNo 再 sellerOrderNo 尝试命中同一出库单。编排时可将客户口述的任意单号原样传入；若后续要查物流轨迹，可先调用本专家拿到 WO/tracking 再交给轨迹类专家。"
      },
      "maxPackagesPerOrder": {
        "type": "integer",
        "description": "剪枝：每单保留包裹数上限；与 prune-outbound-json 默认一致",
        "default": 10,
        "minimum": 1
      },
      "maxMerchandisePerPackage": {
        "type": "integer",
        "description": "剪枝：每包裹保留商品行上限；与 prune-outbound-json 默认一致",
        "default": 20,
        "minimum": 1
      },
      "includeItemList": {
        "type": "boolean",
        "description": "剪枝：是否保留商品明细行；默认 false",
        "default": false
      }
    }
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "structured": {
        "type": "object",
        "description": "结构化数据"
      },
      "analysis": {
        "type": "string",
        "description": "状态解读与说明"
      }
    }
  }
}

