inputSchema:
{
  "type": "object",
  "x_constraint": "本专家不自行拉取轨迹，正式编排建议前置 delivery-status 并把轨迹事实放入 enrichedContext、分析结论放入 inputContext.previousOutput.analysis。JSON Schema 不强制 required，以支持降级调用与补充信息分支。",
  "x_invoke_contract": "编排闭环建议调用 JSON 顶层包含 inputContext.previousOutput.analysis（上游分析）与 sourceExpertId。inputs.enrichedContext 建议包含 recognizedException/ascanDetected/noUpdateDays/hasClaimService/isDomestic/isPlatformWaybill 等事实字段；3PL 平台面单（isPlatformWaybill=true）不支持索赔。缺失时本专家会走 need_info 或 need_human。",
  "properties": {
    "trackingIds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "轨迹单号"
    },
    "outboundOrderNos": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "出库单号"
    },
    "enrichedContext": {
      "type": "object",
      "description": "上游传入的轨迹事实与分支字段（推荐由 delivery-status 合并）",
      "properties": {
        "recognizedException": {
          "type": "boolean",
          "description": "是否命中系统异常识别结果"
        },
        "exceptionResult": {
          "type": "object",
          "description": "异常识别详情"
        },
        "ascanDetected": {
          "type": "boolean",
          "description": "是否有首扫/MSCAN"
        },
        "lastTrackingAt": {
          "type": "string",
          "description": "最后一条轨迹时间"
        },
        "noUpdateDays": {
          "type": "number",
          "description": "轨迹停滞天数"
        },
        "hasClaimService": {
          "type": "boolean",
          "description": "是否有索赔服务"
        },
        "isPlatformWaybill": {
          "type": "boolean",
          "description": "是否为 3PL / 平台面单（此类订单不支持索赔；可由 outbound-order-status 或上游 analysis 判定）"
        },
        "isDomestic": {
          "type": "boolean",
          "description": "是否国内件"
        },
