    "轨迹分析",
    "异常识别"
  ],
  "version": "0.2.1",
  "x_framework_input_required": [
    "inputContext"
  ],
  "x_framework_require_previous_output": true,
  "x_recaller_propagate_previous_enriched_context": true,
  "x_recaller_enriched_context_preferred_source_experts": [
    "delivery-status"
  ],
  "inputSchema": {
    "type": "object",
    "x_constraint": "本专家不自行拉取轨迹，正式编排建议前置 delivery-status 并把轨迹事实放入 enrichedContext、分析结论放入 inputContext.previousOutput.analysis。JSON Schema 不强制 required，以支持降级调用与补充信息分支。",
    "x_invoke_contract": "编排闭环建议调用 JSON 顶层包含 inputContext.previousOutput.analysis（上游分析）与 sourceExpertId。inputs.enrichedContext 建议包含 recognizedException/ascanDetected/noUpdateDays/hasClaimService/isDomestic/isPlatformWaybill 等事实字段；3PL 平台面单（isPlatformWaybill=true）不支持索赔。缺失时本专家会走 need_info 或 need_human。",
