        },
        "dataCompleteness": {
          "type": "string"
        },
        "keyFacts": {
          "type": "array"
        },
        "unconfirmedItems": {
          "type": "array"
        },
        "evidenceRefs": {
          "type": "array"
        }
      }
    },
    "analysis": {
      "type": "string",
      "description": "对客自然语言摘要：直接回答用户问题，并展示带日期的关键依据与未确认项；不得提及内部来源或输出完整聊天记录"
