outputSchema:
{
  "type": "object",
  "properties": {
    "structured": {
      "type": "object",
      "description": "尾程面单查询结果",
      "properties": {
        "status": {
          "type": "string",
          "enum": [
            "success",
            "partial_success",
            "failed",
            "need_input",
            "too_many_matches"
          ]
        },
        "requestedIdentifiers": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "orders": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "orderNo": {
                "type": "string"
              },
              "matchedFrom": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "result": {
                "type": "string",
                "enum": [
                  "success",
                  "no_label",
                  "not_found",
                  "not_supported",
                  "forbidden",
                  "service_error"
                ]
              },
              "businessCode": {
                "type": "string"
              },
              "message": {
                "type": "string"
              },
              "labels": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "trackingNo": {
                      "type": "string"
                    },
                    "labelUrls": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "unresolvedIdentifiers": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "identifier": {
                "type": "string"
              },
              "reason": {
                "type": "string"
              }
            }
          }
        },
        "summary": {
          "type": "object",
          "properties": {
            "requestedCount": {
              "type": "integer"
            },
            "resolvedOrderCount": {
              "type": "integer"
            },
            "successOrderCount": {
              "type": "integer"
            },
            "failedOrderCount": {
              "type": "integer"
            },
            "labelFileCount": {
              "type": "integer"
            }
          }
        }
      }
    },
    "analysis": {
      "type": "string",
      "description": "按订单和 trackingNo 列出的临时 PDF 下载链接、有效期与不可用于实际发货打印的提示，以及逐单失败原因"
    }
  }
}

